-- Extra tables the spam-protection migration needs, copied from production's column definitions (2026-10-27,
-- read-only query). Staging only; used by spam_compat.sh. Foreign keys and RLS are left out (not under test here).
create table if not exists public.audit_logs (id uuid not null default gen_random_uuid() primary key, business_id uuid, user_id uuid, action text not null, entity_type text, entity_id uuid, old_data jsonb, new_data jsonb, ip_address inet, user_agent text, created_at timestamptz not null default now());
create table if not exists public.industries (id uuid not null default gen_random_uuid() primary key, name text not null, slug text not null, description text, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.industry_modules (id uuid not null default gen_random_uuid() primary key, industry_id uuid not null, name text not null, slug text not null, description text, is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.business_modules (id uuid not null default gen_random_uuid() primary key, business_id uuid not null, module_id uuid not null, enabled boolean not null default true, configuration jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.sms_messages (id uuid not null default gen_random_uuid() primary key, business_id uuid not null, customer_id uuid, conversation_id uuid, direction text not null, status text not null default 'queued', from_number text, to_number text, message_body text, external_message_id text, sent_at timestamptz, delivered_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.email_messages (id uuid not null default gen_random_uuid() primary key, business_id uuid not null, customer_id uuid, conversation_id uuid, direction text not null, status text not null default 'queued', from_email text, to_email text, cc text, bcc text, subject text, body_text text, body_html text, external_message_id text, sent_at timestamptz, delivered_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.followup_tasks (id uuid not null default gen_random_uuid() primary key, business_id uuid not null, customer_id uuid, appointment_id uuid, call_id uuid, kind text not null, channel text not null default 'call', due_at timestamptz not null, status text not null default 'pending', attempts integer not null default 0, max_attempts integer not null default 2, outcome text, outcome_notes text, provider_call_id text, claimed_at timestamptz, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), entity_ref uuid, vars jsonb not null default '{}'::jsonb);
create table if not exists public.rate_limits (key text not null, window_start timestamptz not null, hits integer not null default 0, primary key (key, window_start));
create table if not exists public.platform_alerts (id uuid not null default gen_random_uuid() primary key, kind text not null, severity text not null default 'warning', business_id uuid, title text not null, detail text, meta jsonb not null default '{}'::jsonb, dedupe_key text not null default '', status text not null default 'open', occurrences integer not null default 1, first_seen_at timestamptz not null default now(), last_seen_at timestamptz not null default now(), notified_at timestamptz, acknowledged_by uuid, acknowledged_at timestamptz, resolved_by uuid, resolved_at timestamptz, resolution_note text);
create unique index if not exists platform_alerts_one_open_idx on public.platform_alerts (kind, coalesce(business_id, '00000000-0000-0000-0000-000000000000'::uuid), dedupe_key) where status <> 'resolved';
grant all on all tables in schema public to service_role;
